CREATE TYPE "public"."financial_account_role" AS ENUM('UNCLASSIFIED', 'ETSY_RECEIVABLE', 'ETSY_PAYOUT_CLEARING', 'PAYONEER', 'BANK', 'TRANSFER_CLEARING', 'SUPPLIER_COST', 'DIRECT_EXPENSE', 'SHARED_EXPENSE', 'REVENUE', 'REFUND');--> statement-breakpoint
ALTER TABLE "financial_accounts" ADD COLUMN "account_role" "financial_account_role" DEFAULT 'UNCLASSIFIED' NOT NULL;--> statement-breakpoint
ALTER TABLE "financial_accounts" ADD CONSTRAINT "financial_account_role_type_valid" CHECK ("financial_accounts"."account_role" = 'UNCLASSIFIED' OR ("financial_accounts"."account_role" IN ('ETSY_RECEIVABLE', 'ETSY_PAYOUT_CLEARING', 'PAYONEER', 'BANK', 'TRANSFER_CLEARING') AND "financial_accounts"."account_type" = 'ASSET') OR ("financial_accounts"."account_role" IN ('SUPPLIER_COST', 'DIRECT_EXPENSE', 'SHARED_EXPENSE') AND "financial_accounts"."account_type" = 'EXPENSE') OR ("financial_accounts"."account_role" = 'REVENUE' AND "financial_accounts"."account_type" = 'INCOME') OR ("financial_accounts"."account_role" = 'REFUND' AND "financial_accounts"."account_type" IN ('INCOME', 'EXPENSE')));